// Extrai dados da payload Evolution v2
const body = $input.first().json.body;
const data = body.data || body;

// Telefone do cliente (Evolution manda como 5511999999999@s.whatsapp.net)
const remoteJid = data.key?.remoteJid || '';
const rawPhone = remoteJid.split('@')[0];

// Nome do cliente (pushName se disponível)
const fromName = data.pushName || null;

// Tipo de mensagem e conteúdo
let text = '';
let type = 'texto';
let anexoUrl = null;

const msg = data.message || {};
if (msg.conversation) {
  text = msg.conversation;
  type = 'texto';
} else if (msg.extendedTextMessage?.text) {
  text = msg.extendedTextMessage.text;
  type = 'texto';
} else if (msg.imageMessage) {
  text = msg.imageMessage.caption || '[imagem]';
  type = 'imagem';
  anexoUrl = msg.imageMessage.url || null;
} else if (msg.audioMessage) {
  text = '[áudio]';
  type = 'audio';
  anexoUrl = msg.audioMessage.url || null;
} else if (msg.documentMessage) {
  text = msg.documentMessage.fileName || '[documento]';
  type = 'documento';
  anexoUrl = msg.documentMessage.url || null;
} else if (msg.locationMessage) {
  const lat = msg.locationMessage.degreesLatitude;
  const lng = msg.locationMessage.degreesLongitude;
  text = `[localização: ${lat}, ${lng}]`;
  type = 'localizacao';
} else {
  text = '[mensagem não suportada]';
}

return [{
  json: {
    fromPhone: '+' + rawPhone,
    fromName,
    text,
    type,
    anexoUrl,
    whatsappMessageId: data.key?.id || null,
    metadata: { source: 'evolution-n8n', instance: body.instance || null }
  }
}];
